"""Containers for embeddings generated by foundation models."""

import dataclasses
import logging

import numpy as np


logger = logging.getLogger(__name__)


@dataclasses.dataclass(frozen=True)
class EmbeddingMetadata:
    """Metadata for an embedding array."""
    model_name: str
    version: str
    dimensions: int
    seed: int
    timestamp: str


class EmbeddingContainer:
    """Container for numpy array and its metadata."""

    def __init__(self, data: np.ndarray, metadata: EmbeddingMetadata) -> None:
        """Initializes the container.

        Args:
            data: The embedding data.
            metadata: Metadata associated with the embedding.
                
        Raises:
            ValueError: If dimensions mismatch.
        """
        if data.shape[-1] != metadata.dimensions:
            raise ValueError(
                f"Data dimension {data.shape[-1]} does not match "
                f"metadata dimension {metadata.dimensions}"
            )
        self.data = data
        self.metadata = metadata
        logger.debug(f"Created EmbeddingContainer for {metadata.model_name}")

    def get_data(self) -> np.ndarray:
        """Retrieves the embedding data."""
        return self.data
